-- Seconda infornata dal libro "Fiori e Piante da Appartamento" (#120
-- espansione catalogo) — 7 nuove specie: Billbergia, Bougainvillea,
-- Browallia, Brunfelsia, Calceolaria, Campanula, Celosia.
--
-- Calathea, incontrata nello stesso blocco di pagine, è stata saltata:
-- già presente e verificata nel catalogo.
--
-- Bougainvillea e Browallia: segnalate piante velenose (simbolo "!"
-- esplicito nel libro).
--
-- Campanula e Celosia: discrepanza reale fonte/testo sul simbolo "pieno
-- sole" (il testo raccomanda esplicitamente di proteggerle dal sole
-- diretto) — seguito il testo, più specifico, come già fatto per
-- Acalypha nel batch 1.
--
-- giorni_germinazione/trapianto/raccolta lasciati null: il libro non
-- fornisce conteggi di giorni precisi.

insert into specie
  (nome, nome_scientifico, famiglia_botanica, descrizione, esigenze, alert, manutenzione, ciclo_colturale, vaso, ciclo_vitale, slug, fonti, stato_verifica, verificata_il, verificata_da)
values
($t$Billbergia$t$, $t$Billbergia$t$, $t$Bromeliaceae$t$, $t$Genere di 60 specie epifite e numerosi ibridi, arbustivi perenni, originari delle regioni tropicali e subtropicali dell'America. Rosetta di foglie sessili coriacee verde scuro; infiorescenze spiciformi pendule o erette blu, rosse, porpora o bianche, con brattee dai colori vivaci.$t$, $j${"luce": "Mezz'ombra: posizione luminosa ma non esposta al sole", "acqua": "Regolare con acqua non calcarea, versata anche nella rosetta centrale; nebulizzare in estate", "terreno": "Leggero: miscela di pacciame, radici di felci e sfagno"}$j$::jsonb, ARRAY[$t$non tollera temperature inferiori a 12°C$t$, $t$durante la fioritura preferisce una posizione più ombreggiata$t$, $t$il periodo di fioritura non è fisso: viene innescato da uno sbalzo di temperatura (es. passaggio a un locale caldo dopo un periodo freddo, o viceversa)$t$, $t$concimare versando il fertilizzante (mezza dose) nell'acqua delle innaffiature, anche nella rosetta$t$, $t$si moltiplica recidendo le rosette figlie quando raggiungono un'altezza pari alla metà della pianta madre$t$, $t$rinvasare ogni anno$t$], $j${"irrigazione": {"primavera": "regolare, acqua non calcarea, anche nella rosetta", "estate": "regolare + nebulizzazioni", "autunno": "ridotta", "inverno": "diradata"}, "concimazione": {"primavera": "una volta al mese, mezza dose", "estate": "una volta al mese, mezza dose", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "nessuna", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Bromeliaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": ["primavera"], "resistenza_gelo": "nessuna", "spaziatura_cm": 40, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 2, "rinvaso_ogni_mesi": 12, "irrigazione_fattore": 0.9}$j$::jsonb, $t$perenne$t$, $t$billbergia$t$, ARRAY[$t$Fiori e Piante da Appartamento (collana Fiori & Piante, Edicart/Royal Smeets Offset, 1995) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$),
($t$Bougainvillea$t$, $t$Bougainvillea$t$, $t$Nyctaginaceae$t$, $t$Genere originario dell'America meridionale (Brasile in particolare), diffuso anche nell'Europa meridionale come pianta da giardino. Rami spinosi, foglie ovali acuminate, piccoli fiori bianchi circondati da vistose brattee rosa, rosse, porpora o arancioni.$t$, $j${"luce": "Pieno sole", "acqua": "Regolare, abbondante durante la fioritura, con nebulizzazioni", "terreno": "Umido, ricco di humus"}$j$::jsonb, ARRAY[$t$pianta velenosa (simbolo esplicito nel libro)$t$, $t$rami spinosi: attenzione nella manipolazione$t$, $t$prima della vendita le piante vengono immerse in una soluzione anticaduta boccioli: una prima perdita di boccioli quando l'effetto svanisce è normale$t$, $t$in inverno: posizione luminosa a 5-10°C, diradare le annaffiature (la caduta delle foglie in questo periodo è normale)$t$, $t$aumentare le annaffiature gradualmente quando spuntano i primi boccioli: riprenderle troppo presto può compromettere la fioritura$t$, $t$cimare regolarmente i germogli per una fioritura più abbondante; potare radicalmente subito dopo la fioritura$t$, $t$rinvasare ogni due-tre anni, in primavera$t$], $j${"irrigazione": {"primavera": "regolare", "estate": "abbondante, con nebulizzazioni", "autunno": "diradare gradualmente", "inverno": "diradata, terreno mai secco del tutto"}, "concimazione": {"primavera": "settimanale", "estate": "settimanale", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "nessuna", "estate": "cimare i germogli per favorire la fioritura", "autunno": "potatura radicale dopo la fioritura", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Nyctaginaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": ["primavera"], "resistenza_gelo": "nessuna", "spaziatura_cm": 60, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 10, "rinvaso_ogni_mesi": 30, "irrigazione_fattore": 0.8}$j$::jsonb, $t$perenne$t$, $t$bougainvillea$t$, ARRAY[$t$Fiori e Piante da Appartamento (collana Fiori & Piante, Edicart/Royal Smeets Offset, 1995) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$),
($t$Browallia$t$, $t$Browallia$t$, $t$Solanaceae$t$, $t$Genere erbaceo ramificato originario delle regioni tropicali dell'America meridionale, fusti flessibili verde scuro. Fiori blu, porpora o bianchi a calice imbutiforme con 5 petali ampi e diseguali, solitari all'ascella delle foglie o in racemi.$t$, $j${"luce": "Mezz'ombra", "acqua": "Regolare, terreno mai secco del tutto", "terreno": "Per vasi, poroso, ricco di humus"}$j$::jsonb, ARRAY[$t$pianta velenosa (simbolo esplicito nel libro)$t$, $t$se la semina viene effettuata in luglio/agosto, le piante fioriscono anche in inverno$t$, $t$cimare regolarmente i germogli incipienti per una fioritura più abbondante$t$, $t$rimuovere subito i fiori appassiti$t$, $t$tutte le parti della pianta sono appiccicose (B. viscosa)$t$, $t$temperatura ideale 15-18°C$t$], $j${"irrigazione": {"primavera": "regolare", "estate": "regolare", "autunno": "ridotta", "inverno": "diradata, terreno mai secco"}, "concimazione": {"primavera": "settimanale", "estate": "settimanale", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "cimare i germogli", "estate": "cimare i germogli", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Solanaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": ["primavera", "estate"], "finestra_trapianto": ["primavera"], "resistenza_gelo": "nessuna", "spaziatura_cm": 25, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 2, "rinvaso_ogni_mesi": null, "irrigazione_fattore": 0.8}$j$::jsonb, $t$annuale$t$, $t$browallia$t$, ARRAY[$t$Fiori e Piante da Appartamento (collana Fiori & Piante, Edicart/Royal Smeets Offset, 1995) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$),
($t$Brunfelsia$t$, $t$Brunfelsia$t$, $t$Solanaceae$t$, $t$Genere di piante perenni nativo delle regioni tropicali dell'America centrale e meridionale, foglie lanceolate verde lucido, lunga corolla tubolare e grandi fiori piatti azzurri, gialli o bianchi (spesso cambiano colore con l'età, da porpora-violaceo a bianco).$t$, $j${"luce": "Mezz'ombra: posizione luminosa, protetta dal sole", "acqua": "Regolare durante vegetazione e fioritura", "terreno": "Terra per vasi umida, non alcalina"}$j$::jsonb, ARRAY[$t$richiede molta umidità ambientale: nebulizzare di frequente$t$, $t$periodo di riposo da novembre a gennaio: temperatura non superiore a 15°C, posizione ombreggiata, annaffiature diradate$t$, $t$dopo il riposo, spostare gradualmente in ambienti più caldi e riprendere le annaffiature$t$, $t$concimare con fertilizzante ricco di azoto alla ripresa vegetativa, per mantenere il colore delle foglie$t$, $t$se necessario, rinvasare in primavera effettuando una potatura radicale$t$], $j${"irrigazione": {"primavera": "regolare", "estate": "regolare", "autunno": "diradata (riposo da novembre)", "inverno": "diradata, riposo a max 15°C"}, "concimazione": {"primavera": "settimanale, ricco di azoto alla ripresa", "estate": "settimanale", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "potatura radicale se rinvasata", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Solanaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": ["primavera"], "resistenza_gelo": "nessuna", "spaziatura_cm": 40, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 5, "rinvaso_ogni_mesi": 24, "irrigazione_fattore": 0.8}$j$::jsonb, $t$perenne$t$, $t$brunfelsia$t$, ARRAY[$t$Fiori e Piante da Appartamento (collana Fiori & Piante, Edicart/Royal Smeets Offset, 1995) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$),
($t$Calceolaria$t$, $t$Calceolaria$t$, $t$Calceolariaceae$t$, $t$Il nome deriva dal latino calceolus, "scarpina", per la forma particolare della corolla. Genere proveniente dalle regioni montuose dell'America meridionale; le varietà coltivate sono per lo più ibridi ('Multiflora', 'Crenatiflora'), a fiori maculati o marmorizzati, gialli, rossi, arancioni o porpora.$t$, $j${"luce": "Mezz'ombra: posizione luminosa ma non esposta a correnti d'aria dirette né ai raggi diretti del sole", "acqua": "Regolare, senza bagnare i fiori", "terreno": "Ricco di ferro, molto acido, terriccio speciale"}$j$::jsonb, ARRAY[$t$ciclo di vita molto breve: la fioritura dura circa quattro settimane, poi la pianta muore (annuale da rinnovare)$t$, $t$molto sensibile agli afidi, soprattutto se il terreno viene lasciato asciugare$t$, $t$recidere subito i fiori appassiti$t$, $t$temperatura ideale 16-18°C$t$], $j${"irrigazione": {"primavera": "regolare", "estate": "regolare", "autunno": "regolare", "inverno": "regolare"}, "concimazione": {"primavera": null, "estate": null, "autunno": null, "inverno": null}, "potatura": {"primavera": "nessuna", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Calceolariaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": ["primavera", "autunno"], "resistenza_gelo": "nessuna", "spaziatura_cm": 20, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 1, "rinvaso_ogni_mesi": null, "irrigazione_fattore": 0.7}$j$::jsonb, $t$annuale$t$, $t$calceolaria$t$, ARRAY[$t$Fiori e Piante da Appartamento (collana Fiori & Piante, Edicart/Royal Smeets Offset, 1995) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$),
($t$Campanula$t$, $t$Campanula isophylla$t$, $t$Campanulaceae$t$, $t$Genere originario delle regioni temperate dell'emisfero boreale, in particolare mediterranee. Verificata su C. isophylla ("stella d'Italia"), l'unica specie del genere adatta alla coltivazione in appartamento: fusti striscianti pelosi e grandi fiori blu chiaro a stella, a 5 petali.$t$, $j${"luce": "Molto luminosa, ma protetta dalla luce diretta del sole", "acqua": "Regolare, più abbondante in stagione calda", "terreno": "Sostanzioso, ricco di humus: pacciame, argilla e concime organico"}$j$::jsonb, ARRAY[$t$il libro riporta il simbolo "pieno sole", ma il testo raccomanda di proteggerla dalla luce diretta: seguito il testo$t$, $t$recidere i fiori appassiti$t$, $t$potare la pianta dopo la fioritura$t$, $t$in inverno il vaso va posto in posizione luminosa a 8-10°C$t$, $t$rinvasare in primavera$t$], $j${"irrigazione": {"primavera": "regolare", "estate": "abbondante", "autunno": "regolare", "inverno": "diradata se ambiente freddo, abbondante se caldo"}, "concimazione": {"primavera": "settimanale", "estate": "settimanale", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "nessuna", "estate": "recidere i fiori appassiti", "autunno": "potatura dopo la fioritura", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Campanulaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": ["primavera"], "resistenza_gelo": "nessuna", "spaziatura_cm": 25, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 2, "rinvaso_ogni_mesi": 12, "irrigazione_fattore": 0.8}$j$::jsonb, $t$perenne$t$, $t$campanula$t$, ARRAY[$t$Fiori e Piante da Appartamento (collana Fiori & Piante, Edicart/Royal Smeets Offset, 1995) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$),
($t$Celosia$t$, $t$Celosia argentea$t$, $t$Amaranthaceae$t$, $t$Unica specie coltivata del genere, indigena dell'Indonesia. Due varietà: 'Plumosa', con spighe terminali piumose piramidali (adatta a fiori recisi), e 'Cristata' ("cresta di gallo"), con infiorescenze larghe e sinuose, entrambe in rosso, rosa, arancione, porpora, crema o giallo.$t$, $j${"luce": "Molto luminosa, ma non esposta al sole diretto", "acqua": "Regolare, terreno sempre umido ma non troppo", "terreno": "Sostanzioso, ben drenato"}$j$::jsonb, ARRAY[$t$il libro riporta il simbolo "pieno sole", ma il testo raccomanda di non esporla al sole diretto: seguito il testo$t$, $t$dopo la fioritura la pianta muore (annuale)$t$, $t$la varietà 'Cristata' ha bisogno di molta aria fresca$t$, $t$la varietà 'Plumosa' è adatta a fiori recisi e a bordure/aiuole$t$, $t$semina a febbraio/marzo o aprile/maggio$t$], $j${"irrigazione": {"primavera": "regolare", "estate": "regolare, terreno sempre umido", "autunno": "nessuna (ciclo esaurito)", "inverno": "nessuna"}, "concimazione": {"primavera": "regolare", "estate": "regolare", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "nessuna", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Amaranthaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": ["inverno", "primavera"], "finestra_trapianto": ["primavera"], "resistenza_gelo": "nessuna", "spaziatura_cm": 20, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 2, "rinvaso_ogni_mesi": null, "irrigazione_fattore": 0.7}$j$::jsonb, $t$annuale$t$, $t$celosia$t$, ARRAY[$t$Fiori e Piante da Appartamento (collana Fiori & Piante, Edicart/Royal Smeets Offset, 1995) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$);
